package br.com.portalmanager.platform.workspace.entrypoint.web.environment;
import br.com.portalmanager.platform.workspace.core.environment.facade.EnvironmentTypeCompatibilityFacade;import br.com.portalmanager.platform.workspace.entrypoint.web.environment.request.CreateEnvironmentTypeCompatibilityRequest;import br.com.portalmanager.platform.workspace.entrypoint.web.environment.response.EnvironmentTypeCompatibilityResponse;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import java.util.List;
@RestController @RequestMapping("/api/v1/environment-types/compatibilities") public class EnvironmentTypeCompatibilityController {private final EnvironmentTypeCompatibilityFacade facade;public EnvironmentTypeCompatibilityController(EnvironmentTypeCompatibilityFacade f){facade=f;}
@GetMapping public List<EnvironmentTypeCompatibilityResponse> list(@RequestParam(required=false) String lifecycle){return facade.list(lifecycle).stream().map(EnvironmentTypeCompatibilityResponse::from).toList();}
@PostMapping public ResponseEntity<EnvironmentTypeCompatibilityResponse> allow(@RequestBody CreateEnvironmentTypeCompatibilityRequest r){String p=r==null?null:r.parentTypeCode(),c=r==null?null:r.childTypeCode();return ResponseEntity.status(HttpStatus.CREATED).body(EnvironmentTypeCompatibilityResponse.from(facade.allow(p,c)));}
@PostMapping("/{identifier}/inactivate") public ResponseEntity<Void> disallow(@PathVariable String identifier){facade.disallow(identifier);return ResponseEntity.noContent().build();}
@DeleteMapping("/{identifier}") public ResponseEntity<Void> delete(@PathVariable String identifier){facade.delete(identifier);return ResponseEntity.noContent().build();}}
